import{_ as e,o,c as l,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2017-SEP-06 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"2017-SEP-06 :: Ceph Developer Monthly","date":"2017-09-12T00:00:00.000Z","updated":"2017-09-12T00:00:00.000Z","tags":["Ceph","distributed storage","CRUSH algorithm","high availability","scalability","object storage","block storage","file system storage","consistency","decentralization","performance"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-SEP-06_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2017/2017-SEP-06_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780459816000}'),r={name:"posts/2017/2017-SEP-06_-_-_Ceph_Developer_Monthly.md"};function i(n,t,p,_,a,g){return o(),l("div",null,[...t[0]||(t[0]=[s("<p>在本次Ceph开发者月度会议上，讨论了多个Ceph存储集群的优化方案，并制定了后续行动计划。以下为会议的主要内容：</p><p><strong>一、Ceph存储集群优化</strong></p><ol><li><strong>跨数据中心复制</strong>： 讨论了实现跨数据中心复制时维护全局顺序的挑战，并提出使用时间切片和定时器来同步客户端操作的机制。</li><li><strong>保证复制正确性</strong>： 讨论了在发生OSD故障时保证复制正确性的方法，并提出了使用原始操作日志和快照来保证对象正确性的方法。</li><li><strong>共享RBD客户端缓存</strong>： 讨论了共享RBD客户端缓存的设计，并提出了使用共享内存和IPC机制来实现缓存共享。</li><li><strong>统一PG日志修剪</strong>： 讨论了优化PG日志管理的方法，并提出了使用时间戳和全局LRU来修剪PG日志。</li><li><strong>去重</strong>： 讨论了在Ceph存储集群中实现数据去重的方法，并提出了使用对象映射和内容地址存储池来实现去重。</li><li><strong>删除快照</strong>： 讨论了优化删除快照性能的方法，并提出了从OSD映射中移除已删除快照的方法。</li></ol><p><strong>二、其他议题</strong></p><ol><li><strong>统一QoS</strong>： 讨论了在Ceph存储集群中实现统一QoS的方法，并提出了使用QoS策略和QoS表来实现QoS控制。</li><li><strong>M Clock</strong>： 讨论了优化M Clock性能的方法，并提出了使用分片和线程池来提高M Clock性能。</li></ol><p><strong>三、行动计划</strong></p><ul><li>继续优化跨数据中心复制和保证复制正确性的方法。</li><li>实现共享RBD客户端缓存和统一PG日志修剪。</li><li>推进去重和删除快照的功能。</li><li>实现统一QoS和M Clock优化。</li></ul><p>本次会议讨论了Ceph存储集群的多个优化方案，并制定了后续行动计划。这些优化方案将有助于提高Ceph存储集群的性能和可靠性。</p>",8)])])}const C=e(r,[["render",i]]);export{h as __pageData,C as default};
